---- THIS HOST ----
-------------------

-- Same config on both machines: "arch" is the laptop, "arch-pc" the desktop
-- (US keyboard, NVIDIA card, no built-in screen or battery)
local function readHostname()
    local f = io.open("/etc/hostname")
    if not f then return "" end
    local name = f:read("l") or ""
    f:close()
    return name
end

local isDesktop = readHostname() == "arch-pc"


------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/configuring/core/monitors/
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})

if isDesktop then
    -- Desktop: 27" Samsung on DP (main, highest refresh rate) on the left,
    -- 22" Samsung on HDMI to its right
    hl.monitor({
        output   = "DP-3",
        mode     = "highrr",
        position = "0x0",
        scale    = 1,
    })
    hl.monitor({
        output   = "HDMI-A-1",
        mode     = "preferred",
        position = "2560x0",
        scale    = 1,
    })
else
    -- HDMI screen sits to the left of the built-in one
    hl.monitor({
        output   = "HDMI-A-1",
        mode     = "preferred",
        position = "0x0",
        scale    = "auto",
    })
end

-- Built-in screen: scale 1 on its own, 1.5 as a second monitor next to the HDMI
local function applyLaptopScale()
    hl.monitor({
        output   = "eDP-1",
        mode     = "preferred",
        position = "1920x0",
        scale    = hl.get_monitor("HDMI-A-1") and 1.5 or 1,
    })
end

-- Waybar follows along: full bar when alone, reduced bar on the laptop with the HDMI
local waybarConfig = nil

local function refreshMonitorLayout()
    if not isDesktop then
        applyLaptopScale()
    end

    local config
    if isDesktop then
        config = "config-pc"
    else
        config = hl.get_monitor("HDMI-A-1") and "config-dual" or "config"
    end
    if config ~= waybarConfig then
        waybarConfig = config
        hl.exec_cmd("pkill -x waybar; waybar -c $HOME/.config/waybar/" .. config)
    end
end

-- Wait a moment so the monitor list is up to date when the refresh runs
local function scheduleMonitorRefresh()
    hl.timer(refreshMonitorLayout, { timeout = 500, type = "oneshot" })
end

if not isDesktop then
    applyLaptopScale()
end
hl.on("hyprland.start", scheduleMonitorRefresh)
hl.on("monitor.added", scheduleMonitorRefresh)
hl.on("monitor.removed", scheduleMonitorRefresh)


