-- Layout "grilla": las ventanas tiladas en cuadrícula (4 → 2x2), ordenadas por título.
-- Lo usa el workspace 10 para camaras-depo.sh (mpv con títulos "Cam A".."Cam D"),
-- así cada cámara cae siempre en su lugar y Super+V la saca/vuelve a la grilla.
hl.layout.register("grilla", {
    recalculate = function(ctx)
        local targets = {}
        for _, t in ipairs(ctx.targets) do table.insert(targets, t) end
        table.sort(targets, function(a, b)
            local ta = a.window and a.window.title or ""
            local tb = b.window and b.window.title or ""
            if ta == tb then return a.index < b.index end
            return ta < tb
        end)
        local n = #targets
        local cols = math.ceil(math.sqrt(n))
        local rows = math.ceil(n / cols)
        for i, t in ipairs(targets) do
            t:place(ctx:grid_cell(i, cols, rows))
        end
    end,
})

hl.workspace_rule({ workspace = "10", layout = "lua:grilla" })
